// Extract and enrich error context from webhook payload
const items = $input.all();

const enrichedErrors = items.map(item => {
  // CRITICAL: Webhook data is under .body
  const errorData = item.json.body || item.json;

  const now = new Date();
  const errorId = `ERR-${now.getTime()}-${Math.random().toString(36).substr(2, 9)}`;

  // Extract error details
  const workflowName = errorData.workflow?.name || 'Unknown Workflow';
  const executionId = errorData.execution?.id || 'Unknown';
  const nodeName = errorData.node?.name || 'Unknown Node';
  const errorMessage = errorData.error?.message || errorData.message || 'No error message';
  const errorStack = errorData.error?.stack || '';

  // Determine severity based on error patterns
  let severity = 'WARNING';
  const criticalKeywords = ['timeout', 'connection refused', 'authentication failed', 'database', 'payment', 'critical'];
  const errorLower = errorMessage.toLowerCase();

  if (criticalKeywords.some(keyword => errorLower.includes(keyword))) {
    severity = 'CRITICAL';
  } else if (errorLower.includes('warning') || errorLower.includes('retry')) {
    severity = 'WARNING';
  } else if (errorLower.includes('info') || errorLower.includes('debug')) {
    severity = 'INFO';
  }

  // Extract performance metrics
  const executionTime = errorData.execution?.stoppedAt 
    ? new Date(errorData.execution.stoppedAt) - new Date(errorData.execution.startedAt)
    : null;

  return {
    json: {
      errorId,
      timestamp: now.toISOString(),
      severity,
      workflow: {
        name: workflowName,
        id: errorData.workflow?.id,
        executionId
      },
      node: {
        name: nodeName,
        type: errorData.node?.type
      },
      error: {
        message: errorMessage,
        stack: errorStack,
        type: errorData.error?.name || 'Error'
      },
      context: {
        environment: process.env.NODE_ENV || 'production',
        n8nVersion: errorData.n8nVersion,
        executionTime,
        retryCount: errorData.retryCount || 0
      },
      metadata: {
        userId: errorData.userId,
        tags: errorData.tags || [],
        customData: errorData.customData || {}
      }
    }
  };
});

return enrichedErrors;

// Record Prometheus metrics
const items = $input.all();

const metrics = items.map(item => {
  const { severity, workflow, error, context } = item.json;

  // Increment error counter by severity
  const metricLabels = {
    severity: severity.toLowerCase(),
    workflow: workflow.name,
    error_type: error.type,
    environment: context.environment
  };

  // Format for Prometheus Pushgateway
  const prometheusMetrics = [
    `# TYPE n8n_workflow_errors_total counter`,
    `n8n_workflow_errors_total{severity="${metricLabels.severity}",workflow="${metricLabels.workflow}",error_type="${metricLabels.error_type}",environment="${metricLabels.environment}"} 1`,
    ``,
    `# TYPE n8n_workflow_execution_time_seconds gauge`,
    context.executionTime ? `n8n_workflow_execution_time_seconds{workflow="${metricLabels.workflow}"} ${context.executionTime / 1000}` : '',
    ``,
    `# TYPE n8n_workflow_retry_count gauge`,
    `n8n_workflow_retry_count{workflow="${metricLabels.workflow}"} ${context.retryCount}`
  ].filter(Boolean).join('\n');

  return {
    json: {
      ...item.json,
      metrics: {
        prometheus: prometheusMetrics,
        labels: metricLabels
      }
    }
  };
});

return metrics;
